    "Complete your garden, not just your cart.": "உங்கள் தோட்டத்தை நிறைவு செய்யுங்கள், உங்கள் கார்ட்டை மட்டும் அல்ல.",
    "Pair a plant with the right pot, growing media and nutrition. Our catalogue brings the complete gardening journey together.": "ஒரு செடியை சரியான தொட்டி, வளர்ப்பு ஊடகம் மற்றும் ஊட்டச்சத்துடன் இணைக்கவும். எங்கள் கேட்டலாக் முழுமையான தோட்டப் பயணத்தை ஒன்றிணைக்கிறது.",
