    "From terrace gardens to full landscaping, our team can help.": "மொட்டை மாடி தோட்டங்கள் முதல் முழு லேண்ட்ஸ்கேப்பிங் வரை, எங்கள் குழு உதவ முடியும்.",
    "Start with easy-care plants, compact-space favourites or fruit and herb growers.": "எளிதில் பராமரிக்கக்கூடிய செடிகள், சிறிய இட விருப்பங்கள் அல்லது பழம்/மூலிகை வளர்ப்பாளர்களுடன் தொடங்குங்கள்.",
    "4.8 / 5 average across 2,400+ orders": "2,400+ ஆர்டர்களில் சராசரி 4.8 / 5",
    "Thoughtful gifts, beautifully packaged.": "சிந்தனையுள்ள பரிசுகள், அழகாக பொதிசெய்யப்பட்டவை.",
    "From festive surprises to corporate gifting, we make every gesture memorable with curated hampers and personalized touches.": "திருவிழா ஆச்சரியங்கள் முதல் கார்ப்பரேட் பரிசுகள் வரை, க்யூரேட் செய்யப்பட்ட ஹாம்பர்கள் மற்றும் தனிப்பயன் தொடுதல்களுடன் ஒவ்வொரு சைகையையும் மறக்க முடியாததாக்குகிறோம்.",
