    "IoT-monitored nurseries": "IoT-கண்காணிக்கப்படும் நர்சரிகள்",
    "Every polyhouse tracks temperature, humidity and soil health in real time.": "ஒவ்வொரு பாலிஹவுஸும் வெப்பநிலை, ஈரப்பதம் மற்றும் மண் ஆரோக்கியத்தை நேரடியாகக் கண்காணிக்கிறது.",
    "Precision trials": "துல்லியமான சோதனைகள்",
    "New varieties are tested for months before they ever reach your cart.": "புதிய வகைகள் உங்கள் கார்ட்டை அடைவதற்கு முன் மாதக்கணக்கில் சோதிக்கப்படுகின்றன.",
    "health guarantee": "ஆரோக்கிய உத்தரவாதம்",
    "Plants leave the lab only when they clear our quality checks.": "செடிகள் எங்கள் தர சோதனைகளில் தேர்ச்சி பெற்றால் மட்டுமே ஆய்வகத்தை விட்டு வெளியேறும்.",
    "Expert plant-care guidance": "நிபுணர் செடி பராமரிப்பு வழிகாட்டுதல்",
    "Free care notes and a support line for every plant you buy.": "நீங்கள் வாங்கும் ஒவ்வொரு செடிக்கும் இலவச பராமரிப்பு குறிப்புகள் மற்றும் ஆதரவு வரி.",
    "Verified": "சரிபார்க்கப்பட்டது",
    "How are plants packaged for delivery?": "டெலிவரிக்கு செடிகள் எவ்வாறு பேக் செய்யப்படுகின்றன?",
    "Every plant ships in a secure nursery pot with moisture-locking wrap and a care card, so it arrives ready to repot.": "ஒவ்வொரு செடியும் ஈரப்பத தடுப்பு போர்வையுடன் பாதுகாப்பான நர்சரி பாட்டில் அனுப்பப்படுகிறது, ஒரு பராமரிப்பு அட்டையுடன், மறுநடவுக்குத் தயாராக வரும்.",
    "Do you offer a health guarantee?": "நீங்கள் ஆரோக்கிய உத்தரவாதம் வழங்குகிறீர்களா?",
    "We don't offer refunds, but we'll replace any plant that arrives damaged — just report it with photo proof within 24–48 hours of delivery.": "நாங்கள் பணத் திரும்பப் பெறுதல் வழங்குவதில்லை, ஆனால் சேதமடைந்து வரும் எந்த செடியையும் மாற்றித் தருவோம் — டெலிவரி செய்த 24-48 மணி நேரத்திற்குள் புகைப்பட ஆதாரத்துடன் தெரிவிக்கவும்.",
    "Can I get gardening help after I buy?": "வாங்கிய பிறகு தோட்ட உதவி கிடைக்குமா?",
    "Every order includes access to our plant-care guidance line for as long as you own the plant.": "நீங்கள் செடியை வைத்திருக்கும் வரை ஒவ்வொரு ஆர்டரிலும் எங்கள் செடி பராமரிப்பு வழிகாட்டுதல் வரிக்கான அணுகல் அடங்கும்.",
    "Do you deliver pots and planters separately?": "தொட்டிகள் மற்றும் பாட்களை தனியாக டெலிவரி செய்கிறீர்களா?",
    "Yes, pots, seeds and tools can be ordered on their own or bundled with a plant.": "ஆம், தொட்டிகள், விதைகள் மற்றும் கருவிகளை தனியாகவோ அல்லது ஒரு செடியுடன் இணைத்தோ ஆர்டர் செய்யலாம்.",
    "Do you deliver everywhere in India?": "இந்தியா முழுவதும் டெலிவரி செய்கிறீர்களா?",
    "Yes — we ship pan-India, with same-day delivery available within a 30 km radius. Delivery charges are calculated based on order weight and size.": "ஆம் — நாங்கள் இந்தியா முழுவதும் அனுப்புகிறோம், 30 கிமீ சுற்றளவில் அதே நாள் டெலிவரி கிடைக்கும். டெலிவரி கட்டணம் ஆர்டரின் எடை மற்றும் அளவின் அடிப்படையில் கணக்கிடப்படும்.",
    "Is Cash on Delivery available?": "டெலிவரியில் பணம் செலுத்தும் வசதி உள்ளதா?",
    "Yes, Cash on Delivery is currently available for Chennai only. All other locations are prepaid.": "ஆம், தற்போது சென்னைக்கு மட்டும் கேஷ் ஆன் டெலிவரி உள்ளது. மற்ற இடங்களுக்கு முன்பணமாக செலுத்த வேண்டும்.",
    "We couldn't find that page.": "அந்தப் பக்கம் கிடைக்கவில்லை.",
    "OFFERS": "சலுகைகள்",
    "All offers, in one place": "அனைத்து சலுகைகளும், ஒரே இடத்தில்",
    "Plant bundles, category discounts and seasonal deals across the IGO catalogue.": "IGO கேட்டலாக் முழுவதும் செடி பண்டில்கள், வகை தள்ளுபடிகள் மற்றும் சீசன் சலுகைகள்.",
