    "Tell us about your space": "உங்கள் இடத்தைப் பற்றி எங்களிடம் கூறுங்கள்",
    "Share a few photos and dimensions, and our team will put together a plan and quote.": "சில புகைப்படங்களையும் அளவீடுகளையும் பகிரவும், எங்கள் குழு ஒரு திட்டத்தையும் மேற்கோளையும் தயார் செய்யும்.",
    "Request a consultation": "ஆலோசனை கோருங்கள்",
    "End-to-end landscaping design and build - from a single balcony to a full campus. Browse the services below and reach out for a site visit and quote.": "ஒரு பால்கனியிலிருந்து முழு வளாகம் வரை - முழுமையான லேண்ட்ஸ்கேப்பிங் வடிவமைப்பு மற்றும் கட்டுமானம். கீழே உள்ள சேவைகளை உலாவி, தள பார்வை மற்றும் மேற்கோளுக்கு தொடர்பு கொள்ளுங்கள்.",
    "Care guides and ideas from the IGO Nursery team.": "IGO நர்சரி குழுவின் பராமரிப்பு வழிகாட்டிகள் மற்றும் யோசனைகள்.",
    "OUR STORY": "எங்கள் கதை",
    "Corporate Gifts": "கார்ப்பரேட் பரிசுகள்",
    "Thoughtful, ready-to-gift plants and planters for every occasion.": "ஒவ்வொரு சந்தர்ப்பத்திற்கும் ஏற்ற, பரிசாக வழங்கத் தயாரான செடிகள் மற்றும் தொட்டிகள்.",
    "Results for \"{q}\"": "\"{q}\" க்கான முடிவுகள்",
    "IGO Nursery started as a small AgriTech lab in Muttukadu, testing how IoT monitoring and precision trials could grow healthier plants at scale. Today every plant that reaches your door has passed through that same lab before it ever reaches the catalogue.": "IGO நர்சரி முட்டுக்காடில் ஒரு சிறிய அக்ரிடெக் ஆய்வகமாக தொடங்கியது, IoT கண்காணிப்பு மற்றும் துல்லியமான சோதனைகள் மூலம் ஆரோக்கியமான செடிகளை பெரிய அளவில் வளர்க்க முடியுமா என்பதை சோதித்தது. இன்று உங்கள் வீட்டு வாசலை அடையும் ஒவ்வொரு செடியும் பட்டியலில் சேருவதற்கு முன் அதே ஆய்வகத்தின் வழியாக சென்றுள்ளது.",
    "GALLERY": "கேலரி",
    "Our Gallery": "எங்கள் கேலரி",
    "A look at our nursery, gardens and completed projects.": "எங்கள் நர்சரி, தோட்டங்கள் மற்றும் முடிக்கப்பட்ட திட்டங்களைப் பாருங்கள்.",
    "Photos coming soon — check back for a look at our nursery and completed projects.": "புகைப்படங்கள் விரைவில் வரும் — மீண்டும் பாருங்கள்.",
    "GET IN TOUCH": "தொடர்பில் இருங்கள்",
    "Have a question or need a quote? We'd love to hear from you.": "ஒரு கேள்வி உள்ளதா அல்லது மேற்கோள் தேவையா? உங்களிடமிருந்து கேட்க விரும்புகிறோம்.",
    "Message": "செய்தி",
