    "every day": "தினமும்",
    "Customer visits to the nursery are welcome.": "நர்சரிக்கு வாடிக்கையாளர்கள் வருகை தரலாம்.",
    "CUSTOMER SUPPORT": "வாடிக்கையாளர் ஆதரவு",
    "Available 24/7": "24/7 கிடைக்கும்",
    "FOUNDER": "நிறுவனர்",
    "Dr John Yesudhas": "டாக்டர் ஜான் யேசுதாஸ்",
    "Established": "நிறுவப்பட்டது",
    "Our Vision": "எங்கள் நோக்கம்",
    "To be a trusted name in providing healthy, high-quality plants while promoting greener living spaces.": "ஆரோக்கியமான, உயர்தர செடிகளை வழங்குவதிலும், பசுமையான வாழ்விடங்களை ஊக்குவிப்பதிலும் நம்பகமான பெயராக இருப்பது.",
    "Our Mission": "எங்கள் பணி",
    "To make gardening accessible to everyone by offering a wide variety of plants, expert guidance, and reliable delivery services, while fostering environmental sustainability.": "பரந்த அளவிலான செடிகள், நிபுணர் வழிகாட்டுதல், நம்பகமான டெலிவரி சேவைகளை வழங்குவதன் மூலம் தோட்டக்கலையை அனைவருக்கும் அணுகக்கூடியதாக மாற்றுவது, சுற்றுச்சூழல் நிலைத்தன்மையை மேம்படுத்துவது.",
    "What Makes Us Different": "நாங்கள் ஏன் வேறுபட்டவர்கள்",
    "Wide Plant Variety": "பரந்த செடி வகைகள்",
    "From seedlings to fully grown mature plants, across a wide range of Indoor and Outdoor categories.": "நாற்றுகள் முதல் முழு வளர்ந்த செடிகள் வரை, உள்/வெளி வகைகள் பலவற்றில்.",
    "Founder-Led Expertise": "நிறுவனர் வழிநடத்தும் நிபுணத்துவம்",
    "Personal plant consultation and guidance shaped directly by our founder’s experience.": "எங்கள் நிறுவனரின் அனுபவத்தால் வடிவமைக்கப்பட்ட தனிப்பட்ட செடி ஆலோசனை.",
    "Fast, Premium-Packaged Delivery": "விரைவான, பிரீமியம் பேக்கேஜிங் டெலிவரி",
    "Every plant ships pan-India in secure, protective packaging designed to arrive fresh and undamaged.": "ஒவ்வொரு செடியும் பாதுகாப்பான பேக்கேஜிங்கில் இந்தியா முழுவதும் அனுப்பப்படுகிறது.",
    "Explore Our Plants": "எங்கள் செடிகளை ஆராயுங்கள்",
    "Tech Farming Scientist · TEDx Speaker · Author, Polyhouse Farming": "டெக் ஃபார்மிங் சயின்டிஸ்ட் · TEDx பேச்சாளர் · Polyhouse Farming புத்தக ஆசிரியர்",
    "Dr. John Yesudhas is the CEO of IGO Group, pioneering precision farming, hydroponics and polyhouse projects across India while mentoring the next generation of agripreneurs.": "டாக்டர் ஜான் யேசுதாஸ் IGO குழுமத்தின் CEO ஆவார், இந்தியா முழுவதும் துல்லிய விவசாயம், ஹைட்ரோபோனிக்ஸ் மற்றும் பாலிஹவுஸ் திட்டங்களை முன்னெடுத்து, அடுத்த தலைமுறை விவசாய தொழில்முனைவோருக்கு வழிகாட்டுகிறார்.",
    "Read Dr. John Yesudhas's full story →": "டாக்டர் ஜான் யேசுதாஸின் முழு கதையைப் படியுங்கள் →",
    "Part of the IGO Group": "IGO குழுமத்தின் ஒரு பகுதி",
    "IGO Nursery is part of the IGO Group, whose sister company IGO Agritech Farms brings over a decade of precision farming and agricultural engineering expertise across India.": "IGO நர்சரி என்பது IGO குழுமத்தின் ஒரு பகுதி, அதன் துணை நிறுவனமான IGO அக்ரிடெக் பார்ம்ஸ் இந்தியா முழுவதும் ஒரு தசாப்தத்திற்கும் மேலான துல்லிய விவசாய மற்றும் விவசாய பொறியியல் நிபுணத்துவத்தை கொண்டுள்ளது.",
    "Years of Group Experience": "குழும அனுபவ ஆண்டுகள்",
