    "Pan-India": "இந்தியா முழுவதும்",
    "Presence": "இருப்பு",
    "Visit IGO Agritech Farms →": "IGO அக்ரிடெக் பார்ம்ஸை பார்வையிடவும் →",
    "FIND YOUR PLANT": "உங்கள் செடியைக் கண்டறியவும்",
    "A few quick questions": "சில விரைவான கேள்விகள்",
    "Answer four short questions and we'll point you to plants that actually fit your space.": "நான்கு சிறு கேள்விகளுக்குப் பதிலளியுங்கள், உங்கள் இடத்திற்குப் பொருந்தும் செடிகளை நாங்கள் காண்பிப்போம்.",
