    "Skip the quiz, browse everything →": "வினாடி வினாவைத் தவிர்த்து, அனைத்தையும் உலாவுங்கள் →",
    "Start over": "மீண்டும் தொடங்கு",
    "Browse all plants →": "அனைத்து செடிகளையும் உலாவுங்கள் →",
    "We didn't have a tight match on every answer, so we widened your results to our best picks for the space and budget you chose.": "ஒவ்வொரு பதிலுக்கும் சரியான பொருத்தம் இல்லை, எனவே உங்கள் இட மற்றும் பட்ஜெட்டிற்கு எங்கள் சிறந்த தேர்வுகளுக்கு விரிவுபடுத்தினோம்.",
    "We couldn't find a plant for that combination yet. Try different answers, or browse the full catalogue.": "அந்த சேர்க்கைக்கு இன்னும் செடி கிடைக்கவில்லை. வேறு பதில்களை முயற்சிக்கவும், அல்லது முழு பட்டியலையும் உலாவவும்.",
    "Based on your answers, we picked {count} plant{plural} from our catalogue for you.": "உங்கள் பதில்களின் அடிப்படையில், எங்கள் பட்டியலிலிருந்து {count} செடிகளைத் தேர்ந்தெடுத்தோம்.",
    "Where will your plant live?": "உங்கள் செடி எங்கு வாழும்?",
