    "How are plants packaged for delivery?": "डिलीवरी के लिए पौधों को कैसे पैक किया जाता है?",
    "Every plant ships in a secure nursery pot with moisture-locking wrap and a care card, so it arrives ready to repot.": "हर पौधा नमी-रोधी रैप और केयर कार्ड के साथ एक सुरक्षित नर्सरी पॉट में भेजा जाता है, ताकि यह रीपॉटिंग के लिए तैयार पहुंचे।",
    "Do you offer a health guarantee?": "क्या आप स्वास्थ्य गारंटी देते हैं?",
    "We don't offer refunds, but we'll replace any plant that arrives damaged — just report it with photo proof within 24–48 hours of delivery.": "हम रिफंड नहीं देते, लेकिन क्षतिग्रस्त पहुंचे किसी भी पौधे को बदल देंगे — बस डिलीवरी के 24-48 घंटों के भीतर फ़ोटो प्रमाण के साथ रिपोर्ट करें।",
    "Can I get gardening help after I buy?": "क्या खरीदने के बाद बागवानी सहायता मिल सकती है?",
