    "Do you deliver pots and planters separately?": "क्या आप गमले और प्लांटर अलग से डिलीवर करते हैं?",
    "Yes, pots, seeds and tools can be ordered on their own or bundled with a plant.": "हां, गमले, बीज और उपकरण अकेले या किसी पौधे के साथ बंडल करके ऑर्डर किए जा सकते हैं।",
    "Do you deliver everywhere in India?": "क्या आप पूरे भारत में डिलीवरी करते हैं?",
    "Yes — we ship pan-India, with same-day delivery available within a 30 km radius. Delivery charges are calculated based on order weight and size.": "हां — हम पूरे भारत में शिप करते हैं, 30 किमी के दायरे में उसी दिन डिलीवरी उपलब्ध है। डिलीवरी शुल्क ऑर्डर के वज़न और आकार पर आधारित होता है।",
    "Is Cash on Delivery available?": "क्या कैश ऑन डिलीवरी उपलब्ध है?",
    "Yes, Cash on Delivery is currently available for Chennai only. All other locations are prepaid.": "हां, फिलहाल कैश ऑन डिलीवरी केवल चेन्नई के लिए उपलब्ध है। अन्य सभी जगहों के लिए भुगतान पहले करना होगा।",
