    "Our Story.": "हमारी कहानी.",
    "Anyone can grow": "कोई भी उगा सकता है",
    "something beautiful.": "कुछ खूबसूरत।",
    "We believe that once you feel a real connection to nature,": "हमारा मानना है कि प्रकृति से एक सच्चा जुड़ाव महसूस करने के बाद, ",
    "it stays with you": "वह हमेशा आपके साथ रहता है",
    "- which is why every plant, pot and seed in our catalogue is chosen to make that connection easier to find, whether you're growing your first leaf or your hundredth.": " - इसीलिए हमारे कैटलॉग में हर पौधा, गमला और बीज इस तरह चुना जाता है कि यह जुड़ाव ढूंढना आसान हो जाए, चाहे आप अपना पहला पत्ता उगा रहे हों या सौवां।",
    "Welcome to IGO Nursery, your one-stop gardening shop!": "IGO नर्सरी में आपका स्वागत है, आपकी वन-स्टॉप बागवानी दुकान!",
    "Founder, IGO Nursery": "संस्थापक, IGO नर्सरी",
    "What Our Customers Say": "हमारे ग्राहक क्या कहते हैं",
    "IGO Nursery": "के बारे में",
    "More Than Just Plants — We're a Part of Your Green Journey.": "सिर्फ़ पौधे ही नहीं — हम आपकी हरी-भरी यात्रा का एक हिस्सा हैं।",
    "At IGO Nursery, we believe in the power of plants to bring beauty, wellness and connection. We're passionate about helping you create greener spaces — at home, at work and in the community.": "IGO नर्सरी में, हम पौधों की उस शक्ति में विश्वास करते हैं जो सुंदरता, स्वास्थ्य और जुड़ाव लाती है। हम आपको घर, कार्यस्थल और समुदाय में हरे-भरे स्थान बनाने में मदद करने के लिए उत्साहित हैं।",
    "Lush greenhouse full of nursery plants - Green Spaces, Happier Lives": "नर्सरी पौधों से भरा हरा-भरा ग्रीनहाउस",
    "Growing Greener,": "हरियाली बढ़ाएं,",
    "Growing Better": "बेहतर बढ़ें",
    "IGO Nursery started with a simple idea — to make quality plants and gardening products accessible to everyone. Today, we are a growing community of plant lovers, offering a wide range of healthy plants, quality pots, seeds and gardening essentials. Our goal is to inspire greener living and help you create beautiful, sustainable spaces.": "IGO नर्सरी एक सरल विचार के साथ शुरू हुई — गुणवत्तापूर्ण पौधों और बागवानी उत्पादों को सभी के लिए सुलभ बनाना। आज, हम स्वस्थ पौधों, गुणवत्तापूर्ण गमलों, बीजों और बागवानी की आवश्यक चीज़ों की एक विस्तृत श्रृंखला प्रदान करने वाला पौध-प्रेमियों का एक बढ़ता हुआ समुदाय हैं। हमारा लक्ष्य हरित जीवन को प्रेरित करना और आपको सुंदर, टिकाऊ स्थान बनाने में मदद करना है।",
    "Learn More": "और जानें",
    "A hand holding a small potted plant - From Seed to Green": "एक छोटा गमला पौधा पकड़े हुए हाथ - बीज से हरियाली तक",
    "Years Experience": "वर्षों का अनुभव",
    "Plants Delivered": "पौधे पहुंचाए गए",
    "Plant Varieties": "पौधों की किस्में",
    "Happy Customers": "खुश ग्राहक",
    "OUR VISION": "हमारी दृष्टि",
    "A Greener Tomorrow": "एक हरा-भरा कल",
    "To be a leading nursery brand that inspires everyone to create healthier, greener and more beautiful spaces, while promoting sustainable living for future generations.": "एक अग्रणी नर्सरी ब्रांड बनना जो सभी को स्वस्थ, हरे-भरे और अधिक सुंदर स्थान बनाने के लिए प्रेरित करे, साथ ही आने वाली पीढ़ियों के लिए टिकाऊ जीवन को बढ़ावा दे।",
    "A young seedling growing in soft sunlight": "कोमल धूप में उगता एक नन्हा पौधा",
    "OUR MISSION": "हमारा उद्देश्य",
    "Plants for a Better Life": "बेहतर जीवन के लिए पौधे",
    "To provide high-quality plants, gardening products and expert guidance, making green living simple, accessible and enjoyable for all.": "उच्च गुणवत्ता वाले पौधे, बागवानी उत्पाद और विशेषज्ञ मार्गदर्शन प्रदान करना, ताकि हरित जीवन सभी के लिए सरल, सुलभ और आनंददायक बन सके।",
    "A lush green leafy plant": "हरी-भरी पत्तेदार पौधा",
    "WHAT WE OFFER": "हम क्या प्रदान करते हैं",
    "Everything You Need for a Greener Space": "हरे-भरे स्थान के लिए आपको जो कुछ भी चाहिए",
    "From beautiful plants to essential gardening products, we have everything you need to bring your green vision to life.": "सुंदर पौधों से लेकर ज़रूरी बागवानी उत्पादों तक, आपके हरित सपने को साकार करने के लिए हमारे पास सब कुछ है।",
    "Grow": "अपने",
