    "How are plants packaged for delivery?": "ഡെലിവറിക്കായി ചെടികൾ എങ്ങനെ പാക്ക് ചെയ്യുന്നു?",
    "Every plant ships in a secure nursery pot with moisture-locking wrap and a care card, so it arrives ready to repot.": "ഓരോ ചെടിയും ഈർപ്പം-പൂട്ടുന്ന റാപ്പും കെയർ കാർഡുമായി സുരക്ഷിതമായ നഴ്സറി പോട്ടിൽ അയക്കുന്നു, അതിനാൽ ഇത് റീപോട്ട് ചെയ്യാൻ തയ്യാറായി എത്തുന്നു.",
