    "We don't offer refunds, but we'll replace any plant that arrives damaged — just report it with photo proof within 24–48 hours of delivery.": "ഞങ്ങൾ റീഫണ്ട് നൽകുന്നില്ല, പക്ഷേ കേടായി എത്തുന്ന ഏതൊരു ചെടിയും മാറ്റിനൽകും — ഡെലിവറി കഴിഞ്ഞ് 24-48 മണിക്കൂറിനുള്ളിൽ ഫോട്ടോ തെളിവോടെ റിപ്പോർട്ട് ചെയ്യുക.",
    "Can I get gardening help after I buy?": "വാങ്ങിയ ശേഷം തോട്ട സഹായം ലഭിക്കുമോ?",
    "Every order includes access to our plant-care guidance line for as long as you own the plant.": "നിങ്ങൾ ചെടി കൈവശം വയ്ക്കുന്നിടത്തോളം ഓരോ ഓർഡറിലും ഞങ്ങളുടെ ചെടി പരിചരണ മാർഗ്ഗനിർദ്ദേശ ലൈനിലേക്കുള്ള ആക്സസ് ഉൾപ്പെടുന്നു.",
    "Do you deliver pots and planters separately?": "ചട്ടികളും പ്ലാന്ററുകളും പ്രത്യേകം ഡെലിവർ ചെയ്യുമോ?",
    "Yes, pots, seeds and tools can be ordered on their own or bundled with a plant.": "അതെ, ചട്ടികൾ, വിത്തുകൾ, ഉപകരണങ്ങൾ എന്നിവ ഒറ്റയ്ക്കോ ഒരു ചെടിയോടൊപ്പം ബണ്ടിൽ ചെയ്തോ ഓർഡർ ചെയ്യാം.",
    "Do you deliver everywhere in India?": "ഇന്ത്യയിൽ എല്ലായിടത്തും ഡെലിവറി ചെയ്യുമോ?",
    "Yes — we ship pan-India, with same-day delivery available within a 30 km radius. Delivery charges are calculated based on order weight and size.": "അതെ — ഞങ്ങൾ ഇന്ത്യയിലുടനീളം ഷിപ്പ് ചെയ്യുന്നു, 30 കിമീ ചുറ്റളവിൽ അതേ ദിവസം ഡെലിവറി ലഭ്യമാണ്. ഡെലിവറി ചാർജ് ഓർഡറിന്റെ ഭാരവും വലുപ്പവും അനുസരിച്ച് കണക്കാക്കും.",
    "Is Cash on Delivery available?": "ക്യാഷ് ഓൺ ഡെലിവറി ലഭ്യമാണോ?",
    "Yes, Cash on Delivery is currently available for Chennai only. All other locations are prepaid.": "അതെ, നിലവിൽ ചെന്നൈയിൽ മാത്രം ക്യാഷ് ഓൺ ഡെലിവറി ലഭ്യമാണ്. മറ്റെല്ലായിടത്തും മുൻകൂർ പണമടയ്ക്കണം.",
    "We couldn't find that page.": "ആ പേജ് ഞങ്ങൾക്ക് കണ്ടെത്താനായില്ല.",
    "OFFERS": "ഓഫറുകൾ",
    "All offers, in one place": "എല്ലാ ഓഫറുകളും, ഒരിടത്ത്",
    "Plant bundles, category discounts and seasonal deals across the IGO catalogue.": "IGO കാറ്റലോഗിലുടനീളം ചെടി ബണ്ടിലുകൾ, വിഭാഗ കിഴിവുകൾ, സീസണൽ ഡീലുകൾ.",
    "VISIT US": "ഞങ്ങളെ സന്ദർശിക്കുക",
    "Locate our store": "ഞങ്ങളുടെ സ്റ്റോർ കണ്ടെത്തുക",
