    "We believe that once you feel a real connection to nature,": "പ്രകൃതിയുമായി ഒരു യഥാർത്ഥ ബന്ധം അനുഭവിച്ചാൽ, ",
    "it stays with you": "അത് നിങ്ങളോടൊപ്പം നിലനിൽക്കും",
    "- which is why every plant, pot and seed in our catalogue is chosen to make that connection easier to find, whether you're growing your first leaf or your hundredth.": " - അതുകൊണ്ടാണ് ഞങ്ങളുടെ കാറ്റലോഗിലെ ഓരോ ചെടിയും ചട്ടിയും വിത്തും ആ ബന്ധം കണ്ടെത്താൻ എളുപ്പമാക്കാൻ തിരഞ്ഞെടുക്കുന്നത്, നിങ്ങൾ നിങ്ങളുടെ ആദ്യ ഇല വളർത്തുകയാണെങ്കിലും നൂറാമത്തേതായാലും.",
    "Welcome to IGO Nursery, your one-stop gardening shop!": "IGO നഴ്സറിയിലേക്ക് സ്വാഗതം, നിങ്ങളുടെ വൺ-സ്റ്റോപ്പ് ഗാർഡനിംഗ് ഷോപ്പ്!",
    "Founder, IGO Nursery": "സ്ഥാപകൻ, IGO നഴ്സറി",
    "What Our Customers Say": "ഞങ്ങളുടെ ഉപഭോക്താക്കൾ എന്ത് പറയുന്നു",
    "IGO Nursery": "കുറിച്ച്",
    "More Than Just Plants — We're a Part of Your Green Journey.": "വെറും ചെടികൾ മാത്രമല്ല — നിങ്ങളുടെ പച്ച യാത്രയുടെ ഭാഗമാണ് ഞങ്ങൾ.",
    "At IGO Nursery, we believe in the power of plants to bring beauty, wellness and connection. We're passionate about helping you create greener spaces — at home, at work and in the community.": "IGO നഴ്സറിയിൽ, ഭംഗിയും ക്ഷേമവും ബന്ധവും കൊണ്ടുവരുന്ന ചെടികളുടെ ശക്തിയിൽ ഞങ്ങൾ വിശ്വസിക്കുന്നു. വീട്ടിലും ജോലിസ്ഥലത്തും സമൂഹത്തിലും പച്ചയായ ഇടങ്ങൾ സൃഷ്ടിക്കാൻ നിങ്ങളെ സഹായിക്കുന്നതിൽ ഞങ്ങൾക്ക് അഭിനിവേശമുണ്ട്.",
    "Lush greenhouse full of nursery plants - Green Spaces, Happier Lives": "നഴ്സറി ചെടികൾ നിറഞ്ഞ പച്ചയായ ഹരിതഗൃഹം",
    "Growing Greener,": "കൂടുതൽ പച്ചപ്പോടെ,",
    "Growing Better": "മെച്ചപ്പെട്ട വളർച്ച",
    "IGO Nursery started with a simple idea — to make quality plants and gardening products accessible to everyone. Today, we are a growing community of plant lovers, offering a wide range of healthy plants, quality pots, seeds and gardening essentials. Our goal is to inspire greener living and help you create beautiful, sustainable spaces.": "IGO നഴ്സറി ഒരു ലളിതമായ ആശയത്തോടെ ആരംഭിച്ചു — ഗുണനിലവാരമുള്ള ചെടികളും തോട്ട ഉൽപ്പന്നങ്ങളും എല്ലാവർക്കും ലഭ്യമാക്കുക. ഇന്ന്, ആരോഗ്യമുള്ള ചെടികൾ, ഗുണനിലവാരമുള്ള ചട്ടികൾ, വിത്തുകൾ, തോട്ട അവശ്യവസ്തുക്കൾ എന്നിവയുടെ വിശാലമായ ശ്രേണി വാഗ്ദാനം ചെയ്യുന്ന ചെടിസ്നേഹികളുടെ വളരുന്ന ഒരു സമൂഹമാണ് ഞങ്ങൾ. പച്ചയായ ജീവിതത്തെ പ്രചോദിപ്പിക്കുകയും മനോഹരവും സുസ്ഥിരവുമായ ഇടങ്ങൾ സൃഷ്ടിക്കാൻ നിങ്ങളെ സഹായിക്കുകയും ചെയ്യുക എന്നതാണ് ഞങ്ങളുടെ ലക്ഷ്യം.",
    "Learn More": "കൂടുതൽ അറിയുക",
    "A hand holding a small potted plant - From Seed to Green": "ഒരു ചെറിയ ചട്ടി ചെടി പിടിച്ചിരിക്കുന്ന കൈ - വിത്തിൽ നിന്ന് പച്ചപ്പിലേക്ക്",
    "Years Experience": "വർഷങ്ങളുടെ പരിചയം",
