    "To be a leading nursery brand that inspires everyone to create healthier, greener and more beautiful spaces, while promoting sustainable living for future generations.": "ആരോഗ്യകരവും പച്ചയും കൂടുതൽ മനോഹരവുമായ ഇടങ്ങൾ സൃഷ്ടിക്കാൻ എല്ലാവരെയും പ്രചോദിപ്പിക്കുന്ന ഒരു മുൻനിര നഴ്സറി ബ്രാൻഡ് ആകുക, അതോടൊപ്പം ഭാവി തലമുറകൾക്കായി സുസ്ഥിര ജീവിതം പ്രോത്സാഹിപ്പിക്കുക.",
    "A young seedling growing in soft sunlight": "മൃദുവായ സൂര്യപ്രകാശത്തിൽ വളരുന്ന ഒരു ഇളം തൈ",
    "OUR MISSION": "ഞങ്ങളുടെ ദൗത്യം",
