    "To provide high-quality plants, gardening products and expert guidance, making green living simple, accessible and enjoyable for all.": "ഉയർന്ന നിലവാരമുള്ള ചെടികൾ, തോട്ട ഉൽപ്പന്നങ്ങൾ, വിദഗ്ധ മാർഗനിർദേശം എന്നിവ നൽകി, പച്ചയായ ജീവിതം എല്ലാവർക്കും ലളിതവും ലഭ്യവും ആസ്വാദ്യകരവുമാക്കുക.",
    "A lush green leafy plant": "തഴച്ചുവളരുന്ന പച്ച ഇലകളുള്ള ചെടി",
    "WHAT WE OFFER": "ഞങ്ങൾ വാഗ്ദാനം ചെയ്യുന്നത്",
    "Everything You Need for a Greener Space": "പച്ചയായ ഇടത്തിന് നിങ്ങൾക്ക് വേണ്ടതെല്ലാം",
    "From beautiful plants to essential gardening products, we have everything you need to bring your green vision to life.": "മനോഹരമായ ചെടികൾ മുതൽ അവശ്യ തോട്ട ഉൽപ്പന്നങ്ങൾ വരെ, നിങ്ങളുടെ പച്ചയായ കാഴ്ചപ്പാട് യാഥാർത്ഥ്യമാക്കാൻ വേണ്ടതെല്ലാം ഞങ്ങളുടെ പക്കലുണ്ട്.",
