    "Every plant ships in a secure nursery pot with moisture-locking wrap and a care card, so it arrives ready to repot.": "ప్రతి మొక్క తేమ-లాకింగ్ ర్యాప్ మరియు కేర్ కార్డుతో సురక్షితమైన నర్సరీ కుండలో పంపబడుతుంది, కాబట్టి ఇది రీపాటింగ్‌కు సిద్ధంగా వస్తుంది.",
