    "Do you deliver pots and planters separately?": "మీరు కుండలు మరియు ప్లాంటర్‌లను విడిగా డెలివరీ చేస్తారా?",
    "Yes, pots, seeds and tools can be ordered on their own or bundled with a plant.": "అవును, కుండలు, విత్తనాలు మరియు పనిముట్లను విడిగా లేదా మొక్కతో కలిపి ఆర్డర్ చేయవచ్చు.",
    "Do you deliver everywhere in India?": "మీరు భారతదేశం అంతటా డెలివరీ చేస్తారా?",
    "Yes — we ship pan-India, with same-day delivery available within a 30 km radius. Delivery charges are calculated based on order weight and size.": "అవును — మేము పాన్-ఇండియా షిప్ చేస్తాము, 30 కి.మీ పరిధిలో అదే రోజు డెలివరీ అందుబాటులో ఉంది. డెలివరీ ఛార్జీలు ఆర్డర్ బరువు మరియు పరిమాణం ఆధారంగా లెక్కించబడతాయి.",
