    "IGO Nursery started as a small AgriTech lab in Muttukadu, testing how IoT monitoring and precision trials could grow healthier plants at scale. Today every plant that reaches your door has passed through that same lab before it ever reaches the catalogue.": "IGO నర్సరీ ముట్టుక్కాడులో ఒక చిన్న అగ్రిటెక్ ల్యాబ్‌గా ప్రారంభమైంది, IoT పర్యవేక్షణ మరియు ఖచ్చితమైన ట్రయల్స్ పెద్ద ఎత్తున ఆరోగ్యకరమైన మొక్కలను ఎలా పెంచగలవో పరీక్షించింది. ఈరోజు మీ ఇంటికి చేరే ప్రతి మొక్క కేటలాగ్‌లోకి చేరడానికి ముందు అదే ల్యాబ్ ద్వారా వెళ్ళింది.",
