    "To be a trusted name in providing healthy, high-quality plants while promoting greener living spaces.": "ఆరోగ్యకరమైన, అధిక నాణ్యత గల మొక్కలను అందించడంలో, పచ్చని జీవన ప్రదేశాలను ప్రోత్సహించడంలో విశ్వసనీయమైన పేరుగా నిలవడం.",
    "Our Mission": "మా లక్ష్యం",
    "To make gardening accessible to everyone by offering a wide variety of plants, expert guidance, and reliable delivery services, while fostering environmental sustainability.": "విభిన్న రకాల మొక్కలు, నిపుణుల మార్గదర్శకత్వం, నమ్మకమైన డెలివరీ సేవలను అందించడం ద్వారా తోటపనిని అందరికీ అందుబాటులోకి తీసుకురావడం, పర్యావరణ సుస్థిరతను పెంపొందించడం.",
    "What Makes Us Different": "మేము ఎలా భిన్నం",
    "Wide Plant Variety": "విస్తృత మొక్కల వైవిధ్యం",
    "From seedlings to fully grown mature plants, across a wide range of Indoor and Outdoor categories.": "మొలకల నుండి పూర్తిగా పెరిగిన మొక్కల వరకు, ఇండోర్, అవుట్‌డోర్ కేటగిరీలలో.",
    "Founder-Led Expertise": "వ్యవస్థాపకుని నేతృత్వంలోని నైపుణ్యం",
    "Personal plant consultation and guidance shaped directly by our founder’s experience.": "మా వ్యవస్థాపకుని అనుభవంతో రూపొందించిన వ్యక్తిగత మొక్కల సలహా.",
    "Fast, Premium-Packaged Delivery": "వేగవంతమైన, ప్రీమియం ప్యాకేజింగ్ డెలివరీ",
    "Every plant ships pan-India in secure, protective packaging designed to arrive fresh and undamaged.": "ప్రతి మొక్క సురక్షితమైన ప్యాకేజింగ్‌లో పాన్-ఇండియా పంపబడుతుంది.",
    "Explore Our Plants": "మా మొక్కలను చూడండి",
    "Tech Farming Scientist · TEDx Speaker · Author, Polyhouse Farming": "టెక్ ఫార్మింగ్ సైంటిస్ట్ · TEDx స్పీకర్ · Polyhouse Farming రచయిత",
    "Dr. John Yesudhas is the CEO of IGO Group, pioneering precision farming, hydroponics and polyhouse projects across India while mentoring the next generation of agripreneurs.": "డా. జాన్ యేసుదాస్ IGO గ్రూప్ CEO, భారతదేశం అంతటా ఖచ్చితమైన వ్యవసాయం, హైడ్రోపోనిక్స్, పాలీహౌస్ ప్రాజెక్టులను ముందుండి నడిపిస్తూ తదుపరి తరం వ్యవసాయ పారిశ్రామికవేత్తలకు మార్గదర్శకత్వం వహిస్తున్నారు.",
    "Read Dr. John Yesudhas's full story →": "డా. జాన్ యేసుదాస్ పూర్తి కథను చదవండి →",
    "Part of the IGO Group": "IGO గ్రూప్‌లో భాగం",
    "IGO Nursery is part of the IGO Group, whose sister company IGO Agritech Farms brings over a decade of precision farming and agricultural engineering expertise across India.": "IGO నర్సరీ IGO గ్రూప్‌లో భాగం, దాని సోదర సంస్థ IGO అగ్రిటెక్ ఫార్మ్స్ భారతదేశం అంతటా దశాబ్దానికి పైగా ఖచ్చితమైన వ్యవసాయం మరియు వ్యవసాయ ఇంజనీరింగ్ నైపుణ్యాన్ని తెస్తుంది.",
