    "We couldn't find a plant for that combination yet. Try different answers, or browse the full catalogue.": "ఆ కలయిక కోసం ఇంకా మొక్క కనుగొనబడలేదు. వేరే సమాధానాలను ప్రయత్నించండి, లేదా పూర్తి కేటలాగ్‌ను బ్రౌజ్ చేయండి.",
