    "- which is why every plant, pot and seed in our catalogue is chosen to make that connection easier to find, whether you're growing your first leaf or your hundredth.": " - అందుకే మా కేటలాగ్‌లోని ప్రతి మొక్క, కుండ మరియు విత్తనం ఆ అనుబంధాన్ని సులభంగా కనుగొనేలా ఎంపిక చేయబడింది, మీరు మీ మొదటి ఆకును పెంచుతున్నా లేదా వందవదైనా.",
    "Welcome to IGO Nursery, your one-stop gardening shop!": "IGO నర్సరీకి స్వాగతం, మీ వన్-స్టాప్ గార్డెనింగ్ షాప్!",
