    "IGO Nursery": "గురించి",
    "More Than Just Plants — We're a Part of Your Green Journey.": "కేవలం మొక్కలు మాత్రమే కాదు — మీ పచ్చని ప్రయాణంలో మేము ఒక భాగం.",
    "At IGO Nursery, we believe in the power of plants to bring beauty, wellness and connection. We're passionate about helping you create greener spaces — at home, at work and in the community.": "IGO నర్సరీలో, అందం, శ్రేయస్సు మరియు అనుబంధాన్ని తీసుకువచ్చే మొక్కల శక్తిని మేము నమ్ముతాము. ఇంట్లో, పనిస్థలంలో మరియు సమాజంలో పచ్చని ప్రదేశాలను సృష్టించడంలో మీకు సహాయం చేయడంలో మేము ఆసక్తిగా ఉన్నాము.",
    "Lush greenhouse full of nursery plants - Green Spaces, Happier Lives": "నర్సరీ మొక్కలతో నిండిన పచ్చని గ్రీన్‌హౌస్",
    "Growing Greener,": "మరింత పచ్చగా,",
    "Growing Better": "మెరుగ్గా పెరుగుతూ",
    "IGO Nursery started with a simple idea — to make quality plants and gardening products accessible to everyone. Today, we are a growing community of plant lovers, offering a wide range of healthy plants, quality pots, seeds and gardening essentials. Our goal is to inspire greener living and help you create beautiful, sustainable spaces.": "IGO నర్సరీ ఒక సాధారణ ఆలోచనతో ప్రారంభమైంది — నాణ్యమైన మొక్కలను మరియు తోటపని ఉత్పత్తులను అందరికీ అందుబాటులోకి తీసుకురావడం. ఈరోజు, మేము ఆరోగ్యకరమైన మొక్కలు, నాణ్యమైన కుండలు, విత్తనాలు మరియు తోటపని అవసరాల విస్తృత శ్రేణిని అందిస్తున్న మొక్కల ప్రేమికుల పెరుగుతున్న సంఘం. పచ్చని జీవనాన్ని ప్రేరేపించడం మరియు అందమైన, స్థిరమైన ప్రదేశాలను సృష్టించడంలో మీకు సహాయం చేయడం మా లక్ష్యం.",
    "Learn More": "మరింత తెలుసుకోండి",
    "A hand holding a small potted plant - From Seed to Green": "ఒక చిన్న కుండ మొక్కను పట్టుకున్న చేయి - విత్తనం నుండి పచ్చదనం వరకు",
