    "Pair a plant with the right pot, growing media and nutrition. Our catalogue brings the complete gardening journey together.": "ಒಂದು ಗಿಡವನ್ನು ಸರಿಯಾದ ಪಾಟ್, ಬೆಳವಣಿಗೆಯ ಮಾಧ್ಯಮ ಮತ್ತು ಪೋಷಣೆಯೊಂದಿಗೆ ಜೋಡಿಸಿ. ನಮ್ಮ ಕ್ಯಾಟಲಾಗ್ ಸಂಪೂರ್ಣ ತೋಟಗಾರಿಕೆ ಪ್ರಯಾಣವನ್ನು ಒಟ್ಟುಗೂಡಿಸುತ್ತದೆ.",
