    "Every polyhouse tracks temperature, humidity and soil health in real time.": "ಪ್ರತಿ ಪಾಲಿಹೌಸ್ ತಾಪಮಾನ, ಆರ್ದ್ರತೆ ಮತ್ತು ಮಣ್ಣಿನ ಆರೋಗ್ಯವನ್ನು ನೈಜ ಸಮಯದಲ್ಲಿ ಟ್ರ್ಯಾಕ್ ಮಾಡುತ್ತದೆ.",
    "Precision trials": "ನಿಖರವಾದ ಪ್ರಯೋಗಗಳು",
    "New varieties are tested for months before they ever reach your cart.": "ಹೊಸ ಪ್ರಭೇದಗಳು ನಿಮ್ಮ ಕಾರ್ಟ್ ತಲುಪುವ ಮೊದಲು ತಿಂಗಳುಗಟ್ಟಲೆ ಪರೀಕ್ಷಿಸಲ್ಪಡುತ್ತವೆ.",
    "health guarantee": "ಆರೋಗ್ಯ ಖಾತರಿ",
    "Plants leave the lab only when they clear our quality checks.": "ನಮ್ಮ ಗುಣಮಟ್ಟ ಪರಿಶೀಲನೆಗಳಲ್ಲಿ ಉತ್ತೀರ್ಣರಾದಾಗ ಮಾತ್ರ ಸಸ್ಯಗಳು ಲ್ಯಾಬ್ ಬಿಡುತ್ತವೆ.",
    "Expert plant-care guidance": "ತಜ್ಞ ಸಸ್ಯ ಆರೈಕೆ ಮಾರ್ಗದರ್ಶನ",
    "Free care notes and a support line for every plant you buy.": "ನೀವು ಖರೀದಿಸುವ ಪ್ರತಿ ಸಸ್ಯಕ್ಕೂ ಉಚಿತ ಆರೈಕೆ ಟಿಪ್ಪಣಿಗಳು ಮತ್ತು ಬೆಂಬಲ ಲೈನ್.",
    "Verified": "ಪರಿಶೀಲಿಸಲಾಗಿದೆ",
    "How are plants packaged for delivery?": "ಡೆಲಿವರಿಗಾಗಿ ಸಸ್ಯಗಳನ್ನು ಹೇಗೆ ಪ್ಯಾಕ್ ಮಾಡಲಾಗುತ್ತದೆ?",
    "Every plant ships in a secure nursery pot with moisture-locking wrap and a care card, so it arrives ready to repot.": "ಪ್ರತಿ ಸಸ್ಯವನ್ನು ತೇವಾಂಶ-ಲಾಕಿಂಗ್ ರಾಪ್ ಮತ್ತು ಕೇರ್ ಕಾರ್ಡ್‌ನೊಂದಿಗೆ ಸುರಕ್ಷಿತ ನರ್ಸರಿ ಪಾಟ್‌ನಲ್ಲಿ ಕಳುಹಿಸಲಾಗುತ್ತದೆ, ಆದ್ದರಿಂದ ಇದು ಮರುನೆಡಲು ಸಿದ್ಧವಾಗಿ ಬರುತ್ತದೆ.",
    "Do you offer a health guarantee?": "ನೀವು ಆರೋಗ್ಯ ಖಾತರಿ ನೀಡುತ್ತೀರಾ?",
    "We don't offer refunds, but we'll replace any plant that arrives damaged — just report it with photo proof within 24–48 hours of delivery.": "ನಾವು ರೀಫಂಡ್ ನೀಡುವುದಿಲ್ಲ, ಆದರೆ ಹಾನಿಗೊಳಗಾಗಿ ಬಂದ ಯಾವುದೇ ಸಸ್ಯವನ್ನು ಬದಲಾಯಿಸುತ್ತೇವೆ — ಡೆಲಿವರಿಯ 24-48 ಗಂಟೆಗಳಲ್ಲಿ ಫೋಟೋ ಪುರಾವೆಯೊಂದಿಗೆ ವರದಿ ಮಾಡಿ.",
    "Can I get gardening help after I buy?": "ಖರೀದಿಸಿದ ನಂತರ ತೋಟಗಾರಿಕೆ ಸಹಾಯ ಪಡೆಯಬಹುದೇ?",
    "Every order includes access to our plant-care guidance line for as long as you own the plant.": "ನೀವು ಸಸ್ಯವನ್ನು ಹೊಂದಿರುವವರೆಗೆ ಪ್ರತಿ ಆರ್ಡರ್‌ನಲ್ಲಿ ನಮ್ಮ ಸಸ್ಯ ಆರೈಕೆ ಮಾರ್ಗದರ್ಶನ ಲೈನ್‌ಗೆ ಪ್ರವೇಶ ಸೇರಿದೆ.",
    "Do you deliver pots and planters separately?": "ನೀವು ಪಾಟ್‌ಗಳು ಮತ್ತು ಪ್ಲಾಂಟರ್‌ಗಳನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ಡೆಲಿವರಿ ಮಾಡುತ್ತೀರಾ?",
    "Yes, pots, seeds and tools can be ordered on their own or bundled with a plant.": "ಹೌದು, ಪಾಟ್‌ಗಳು, ಬೀಜಗಳು ಮತ್ತು ಉಪಕರಣಗಳನ್ನು ಒಂಟಿಯಾಗಿ ಅಥವಾ ಸಸ್ಯದೊಂದಿಗೆ ಬಂಡಲ್ ಮಾಡಿ ಆರ್ಡರ್ ಮಾಡಬಹುದು.",
    "Do you deliver everywhere in India?": "ನೀವು ಭಾರತದಾದ್ಯಂತ ಡೆಲಿವರಿ ಮಾಡುತ್ತೀರಾ?",
    "Yes — we ship pan-India, with same-day delivery available within a 30 km radius. Delivery charges are calculated based on order weight and size.": "ಹೌದು — ನಾವು ಪ್ಯಾನ್-ಇಂಡಿಯಾ ಶಿಪ್ ಮಾಡುತ್ತೇವೆ, 30 ಕಿ.ಮೀ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ ಅದೇ ದಿನ ಡೆಲಿವರಿ ಲಭ್ಯವಿದೆ. ಡೆಲಿವರಿ ಶುಲ್ಕವನ್ನು ಆರ್ಡರ್‌ನ ತೂಕ ಮತ್ತು ಗಾತ್ರದ ಆಧಾರದ ಮೇಲೆ ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ.",
    "Is Cash on Delivery available?": "ಕ್ಯಾಶ್ ಆನ್ ಡೆಲಿವರಿ ಲಭ್ಯವಿದೆಯೇ?",
    "Yes, Cash on Delivery is currently available for Chennai only. All other locations are prepaid.": "ಹೌದು, ಪ್ರಸ್ತುತ ಚೆನ್ನೈಗೆ ಮಾತ್ರ ಕ್ಯಾಶ್ ಆನ್ ಡೆಲಿವರಿ ಲಭ್ಯವಿದೆ. ಇತರ ಎಲ್ಲಾ ಸ್ಥಳಗಳಿಗೆ ಮುಂಗಡ ಪಾವತಿ ಅಗತ್ಯ.",
    "We couldn't find that page.": "ಆ ಪುಟ ನಮಗೆ ಕಂಡುಬಂದಿಲ್ಲ.",
    "OFFERS": "ಆಫರ್‌ಗಳು",
    "All offers, in one place": "ಎಲ್ಲಾ ಆಫರ್‌ಗಳು, ಒಂದೇ ಸ್ಥಳದಲ್ಲಿ",
    "Plant bundles, category discounts and seasonal deals across the IGO catalogue.": "IGO ಕ್ಯಾಟಲಾಗ್‌ನಾದ್ಯಂತ ಸಸ್ಯ ಬಂಡಲ್‌ಗಳು, ವರ್ಗ ರಿಯಾಯಿತಿಗಳು ಮತ್ತು ಋತುಮಾನ ಡೀಲ್‌ಗಳು.",
    "VISIT US": "ನಮ್ಮನ್ನು ಭೇಟಿ ಮಾಡಿ",
