    "Request a consultation": "ಸಮಾಲೋಚನೆ ವಿನಂತಿಸಿ",
    "End-to-end landscaping design and build - from a single balcony to a full campus. Browse the services below and reach out for a site visit and quote.": "ಒಂದು ಬಾಲ್ಕನಿಯಿಂದ ಪೂರ್ಣ ಕ್ಯಾಂಪಸ್‌ವರೆಗೆ - ಸಂಪೂರ್ಣ ಲ್ಯಾಂಡ್‌ಸ್ಕೇಪಿಂಗ್ ವಿನ್ಯಾಸ ಮತ್ತು ನಿರ್ಮಾಣ. ಕೆಳಗಿನ ಸೇವೆಗಳನ್ನು ಬ್ರೌಸ್ ಮಾಡಿ ಮತ್ತು ಸೈಟ್ ಭೇಟಿ ಮತ್ತು ಕೋಟ್‌ಗಾಗಿ ಸಂಪರ್ಕಿಸಿ.",
    "Care guides and ideas from the IGO Nursery team.": "IGO ನರ್ಸರಿ ತಂಡದ ಆರೈಕೆ ಗೈಡ್‌ಗಳು ಮತ್ತು ಆಲೋಚನೆಗಳು.",
    "OUR STORY": "ನಮ್ಮ ಕಥೆ",
    "Corporate Gifts": "ಕಾರ್ಪೊರೇಟ್ ಗಿಫ್ಟ್‌ಗಳು",
    "Thoughtful, ready-to-gift plants and planters for every occasion.": "ಪ್ರತಿ ಸಂದರ್ಭಕ್ಕೂ ಸೂಕ್ತವಾದ, ಉಡುಗೊರೆಗೆ ಸಿದ್ಧವಾದ ಗಿಡಗಳು ಮತ್ತು ಪ್ಲಾಂಟರ್‌ಗಳು.",
    "Results for \"{q}\"": "\"{q}\" ಗಾಗಿ ಫಲಿತಾಂಶಗಳು",
    "IGO Nursery started as a small AgriTech lab in Muttukadu, testing how IoT monitoring and precision trials could grow healthier plants at scale. Today every plant that reaches your door has passed through that same lab before it ever reaches the catalogue.": "IGO ನರ್ಸರಿ ಮುಟ್ಟುಕಾಡಿನಲ್ಲಿ ಒಂದು ಸಣ್ಣ ಅಗ್ರಿಟೆಕ್ ಲ್ಯಾಬ್ ಆಗಿ ಪ್ರಾರಂಭವಾಯಿತು, IoT ಮಾನಿಟರಿಂಗ್ ಮತ್ತು ನಿಖರವಾದ ಪ್ರಯೋಗಗಳು ದೊಡ್ಡ ಪ್ರಮಾಣದಲ್ಲಿ ಆರೋಗ್ಯಕರ ಸಸ್ಯಗಳನ್ನು ಹೇಗೆ ಬೆಳೆಸಬಹುದು ಎಂದು ಪರೀಕ್ಷಿಸಿತು. ಇಂದು ನಿಮ್ಮ ಮನೆ ಬಾಗಿಲಿಗೆ ತಲುಪುವ ಪ್ರತಿ ಸಸ್ಯವೂ ಕ್ಯಾಟಲಾಗ್‌ಗೆ ಸೇರುವ ಮೊದಲು ಅದೇ ಲ್ಯಾಬ್ ಮೂಲಕ ಹಾದುಹೋಗಿದೆ.",
    "GALLERY": "ಗ್ಯಾಲರಿ",
    "Our Gallery": "ನಮ್ಮ ಗ್ಯಾಲರಿ",
    "A look at our nursery, gardens and completed projects.": "ನಮ್ಮ ನರ್ಸರಿ, ತೋಟಗಳು ಮತ್ತು ಪೂರ್ಣಗೊಂಡ ಯೋಜನೆಗಳ ಒಂದು ನೋಟ.",
    "Photos coming soon — check back for a look at our nursery and completed projects.": "ಫೋಟೋಗಳು ಶೀಘ್ರದಲ್ಲೇ ಬರುತ್ತಿವೆ — ಮತ್ತೆ ಪರಿಶೀಲಿಸಿ.",
    "GET IN TOUCH": "ಸಂಪರ್ಕದಲ್ಲಿರಿ",
