    "every day": "ಪ್ರತಿದಿನ",
    "Customer visits to the nursery are welcome.": "ನರ್ಸರಿಗೆ ಗ್ರಾಹಕರ ಭೇಟಿಗೆ ಸ್ವಾಗತ.",
