    "Established": "ಸ್ಥಾಪಿಸಲಾಗಿದೆ",
    "Our Vision": "ನಮ್ಮ ದೃಷ್ಟಿಕೋನ",
    "To be a trusted name in providing healthy, high-quality plants while promoting greener living spaces.": "ಆರೋಗ್ಯಕರ, ಉನ್ನತ ಗುಣಮಟ್ಟದ ಸಸ್ಯಗಳನ್ನು ಒದಗಿಸುವಲ್ಲಿ ಮತ್ತು ಹಸಿರು ಜೀವನ ಸ್ಥಳಗಳನ್ನು ಉತ್ತೇಜಿಸುವಲ್ಲಿ ವಿಶ್ವಾಸಾರ್ಹ ಹೆಸರಾಗುವುದು.",
    "Our Mission": "ನಮ್ಮ ಧ್ಯೇಯ",
    "To make gardening accessible to everyone by offering a wide variety of plants, expert guidance, and reliable delivery services, while fostering environmental sustainability.": "ವೈವಿಧ್ಯಮಯ ಸಸ್ಯಗಳು, ತಜ್ಞರ ಮಾರ್ಗದರ್ಶನ ಮತ್ತು ವಿಶ್ವಾಸಾರ್ಹ ಡೆಲಿವರಿ ಸೇವೆಗಳನ್ನು ನೀಡುವ ಮೂಲಕ ತೋಟಗಾರಿಕೆಯನ್ನು ಎಲ್ಲರಿಗೂ ಪ್ರವೇಶಿಸುವಂತೆ ಮಾಡುವುದು, ಪರಿಸರ ಸುಸ್ಥಿರತೆಯನ್ನು ಬೆಳೆಸುವುದು.",
    "What Makes Us Different": "ನಾವು ಹೇಗೆ ಭಿನ್ನ",
    "Wide Plant Variety": "ವಿಶಾಲ ಸಸ್ಯ ವೈವಿಧ್ಯ",
    "From seedlings to fully grown mature plants, across a wide range of Indoor and Outdoor categories.": "ಸಸಿಗಳಿಂದ ಪೂರ್ಣ ಬೆಳೆದ ಸಸ್ಯಗಳವರೆಗೆ, ಒಳಾಂಗಣ ಮತ್ತು ಹೊರಾಂಗಣ ವಿಭಾಗಗಳಲ್ಲಿ.",
    "Founder-Led Expertise": "ಸಂಸ್ಥಾಪಕರ ನೇತೃತ್ವದ ಪರಿಣತಿ",
    "Personal plant consultation and guidance shaped directly by our founder’s experience.": "ನಮ್ಮ ಸಂಸ್ಥಾಪಕರ ಅನುಭವದಿಂದ ರೂಪುಗೊಂಡ ವೈಯಕ್ತಿಕ ಸಸ್ಯ ಸಲಹೆ.",
    "Fast, Premium-Packaged Delivery": "ವೇಗದ, ಪ್ರೀಮಿಯಂ ಪ್ಯಾಕೇಜಿಂಗ್ ಡೆಲಿವರಿ",
    "Every plant ships pan-India in secure, protective packaging designed to arrive fresh and undamaged.": "ಪ್ರತಿ ಸಸ್ಯವನ್ನು ಸುರಕ್ಷಿತ ಪ್ಯಾಕೇಜಿಂಗ್‌ನಲ್ಲಿ ಪ್ಯಾನ್-ಇಂಡಿಯಾ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.",
    "Explore Our Plants": "ನಮ್ಮ ಸಸ್ಯಗಳನ್ನು ನೋಡಿ",
    "Tech Farming Scientist · TEDx Speaker · Author, Polyhouse Farming": "ಟೆಕ್ ಫಾರ್ಮಿಂಗ್ ಸೈಂಟಿಸ್ಟ್ · TEDx ಸ್ಪೀಕರ್ · Polyhouse Farming ಲೇಖಕ",
    "Dr. John Yesudhas is the CEO of IGO Group, pioneering precision farming, hydroponics and polyhouse projects across India while mentoring the next generation of agripreneurs.": "ಡಾ. ಜಾನ್ ಯೇಸುದಾಸ್ IGO ಗ್ರೂಪ್‌ನ CEO ಆಗಿದ್ದು, ಭಾರತದಾದ್ಯಂತ ನಿಖರ ಕೃಷಿ, ಹೈಡ್ರೋಪೋನಿಕ್ಸ್ ಮತ್ತು ಪಾಲಿಹೌಸ್ ಯೋಜನೆಗಳನ್ನು ಮುನ್ನಡೆಸುತ್ತಾ ಮುಂದಿನ ಪೀಳಿಗೆಯ ಕೃಷಿ ಉದ್ಯಮಿಗಳಿಗೆ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತಿದ್ದಾರೆ.",
    "Read Dr. John Yesudhas's full story →": "ಡಾ. ಜಾನ್ ಯೇಸುದಾಸ್ ಅವರ ಪೂರ್ಣ ಕಥೆಯನ್ನು ಓದಿ →",
    "Part of the IGO Group": "IGO ಗ್ರೂಪ್‌ನ ಭಾಗ",
    "IGO Nursery is part of the IGO Group, whose sister company IGO Agritech Farms brings over a decade of precision farming and agricultural engineering expertise across India.": "IGO ನರ್ಸರಿ IGO ಗ್ರೂಪ್‌ನ ಭಾಗವಾಗಿದೆ, ಇದರ ಸಹೋದರ ಸಂಸ್ಥೆ IGO ಅಗ್ರಿಟೆಕ್ ಫಾರ್ಮ್ಸ್ ಭಾರತದಾದ್ಯಂತ ಒಂದು ದಶಕಕ್ಕೂ ಹೆಚ್ಚು ನಿಖರ ಕೃಷಿ ಮತ್ತು ಕೃಷಿ ಎಂಜಿನಿಯರಿಂಗ್ ಪರಿಣತಿಯನ್ನು ತರುತ್ತದೆ.",
