    "Browse all plants →": "ಎಲ್ಲಾ ಸಸ್ಯಗಳನ್ನು ಬ್ರೌಸ್ ಮಾಡಿ →",
    "We didn't have a tight match on every answer, so we widened your results to our best picks for the space and budget you chose.": "ಪ್ರತಿ ಉತ್ತರಕ್ಕೂ ನಿಖರವಾದ ಹೊಂದಾಣಿಕೆ ಸಿಗಲಿಲ್ಲ, ಆದ್ದರಿಂದ ನಿಮ್ಮ ಸ್ಥಳ ಮತ್ತು ಬಜೆಟ್‌ಗಾಗಿ ನಮ್ಮ ಅತ್ಯುತ್ತಮ ಆಯ್ಕೆಗಳಿಗೆ ಫಲಿತಾಂಶಗಳನ್ನು ವಿಸ್ತರಿಸಿದ್ದೇವೆ.",
    "We couldn't find a plant for that combination yet. Try different answers, or browse the full catalogue.": "ಆ ಸಂಯೋಜನೆಗೆ ಇನ್ನೂ ಸಸ್ಯ ಕಂಡುಬಂದಿಲ್ಲ. ವಿಭಿನ್ನ ಉತ್ತರಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ, ಅಥವಾ ಪೂರ್ಣ ಕ್ಯಾಟಲಾಗ್ ಬ್ರೌಸ್ ಮಾಡಿ.",
