    "Our Story.": "ನಮ್ಮ ಕಥೆ.",
    "Anyone can grow": "ಯಾರಾದರೂ ಬೆಳೆಸಬಹುದು",
    "something beautiful.": "ಸುಂದರವಾದದ್ದನ್ನು.",
    "We believe that once you feel a real connection to nature,": "ಪ್ರಕೃತಿಯೊಂದಿಗೆ ನಿಜವಾದ ಸಂಪರ್ಕವನ್ನು ಅನುಭವಿಸಿದ ನಂತರ, ",
    "it stays with you": "ಅದು ನಿಮ್ಮೊಂದಿಗೆ ಉಳಿಯುತ್ತದೆ",
    "- which is why every plant, pot and seed in our catalogue is chosen to make that connection easier to find, whether you're growing your first leaf or your hundredth.": " - ಅದಕ್ಕಾಗಿಯೇ ನಮ್ಮ ಕ್ಯಾಟಲಾಗ್‌ನಲ್ಲಿರುವ ಪ್ರತಿ ಸಸ್ಯ, ಪಾಟ್ ಮತ್ತು ಬೀಜವನ್ನು ಆ ಸಂಪರ್ಕವನ್ನು ಸುಲಭವಾಗಿ ಕಂಡುಕೊಳ್ಳಲು ಆಯ್ಕೆ ಮಾಡಲಾಗುತ್ತದೆ, ನೀವು ನಿಮ್ಮ ಮೊದಲ ಎಲೆಯನ್ನು ಬೆಳೆಸುತ್ತಿರಲಿ ಅಥವಾ ನೂರನೆಯದನ್ನಾಗಲಿ.",
    "Welcome to IGO Nursery, your one-stop gardening shop!": "IGO ನರ್ಸರಿಗೆ ಸ್ವಾಗತ, ನಿಮ್ಮ ಒನ್-ಸ್ಟಾಪ್ ಗಾರ್ಡನಿಂಗ್ ಶಾಪ್!",
    "Founder, IGO Nursery": "ಸಂಸ್ಥಾಪಕರು, IGO ನರ್ಸರಿ",
    "What Our Customers Say": "ನಮ್ಮ ಗ್ರಾಹಕರು ಏನು ಹೇಳುತ್ತಾರೆ",
    "IGO Nursery": "ಬಗ್ಗೆ",
    "More Than Just Plants — We're a Part of Your Green Journey.": "ಕೇವಲ ಸಸ್ಯಗಳು ಮಾತ್ರವಲ್ಲ — ನಿಮ್ಮ ಹಸಿರು ಪಯಣದ ಭಾಗವಾಗಿದ್ದೇವೆ.",
    "At IGO Nursery, we believe in the power of plants to bring beauty, wellness and connection. We're passionate about helping you create greener spaces — at home, at work and in the community.": "IGO ನರ್ಸರಿಯಲ್ಲಿ, ಸೌಂದರ್ಯ, ಯೋಗಕ್ಷೇಮ ಮತ್ತು ಸಂಪರ್ಕವನ್ನು ತರುವ ಸಸ್ಯಗಳ ಶಕ್ತಿಯಲ್ಲಿ ನಾವು ನಂಬಿಕೆ ಇಡುತ್ತೇವೆ. ಮನೆಯಲ್ಲಿ, ಕೆಲಸದ ಸ್ಥಳದಲ್ಲಿ ಮತ್ತು ಸಮುದಾಯದಲ್ಲಿ ಹಸಿರು ಸ್ಥಳಗಳನ್ನು ರಚಿಸಲು ನಿಮಗೆ ಸಹಾಯ ಮಾಡುವಲ್ಲಿ ನಾವು ಉತ್ಸಾಹಿಗಳಾಗಿದ್ದೇವೆ.",
    "Lush greenhouse full of nursery plants - Green Spaces, Happier Lives": "ನರ್ಸರಿ ಸಸ್ಯಗಳಿಂದ ತುಂಬಿದ ಹಸಿರು ಹಸಿರುಮನೆ",
    "Growing Greener,": "ಹೆಚ್ಚು ಹಸಿರಾಗಿ,",
    "Growing Better": "ಉತ್ತಮವಾಗಿ ಬೆಳೆಯುತ್ತಾ",
    "IGO Nursery started with a simple idea — to make quality plants and gardening products accessible to everyone. Today, we are a growing community of plant lovers, offering a wide range of healthy plants, quality pots, seeds and gardening essentials. Our goal is to inspire greener living and help you create beautiful, sustainable spaces.": "IGO ನರ್ಸರಿ ಒಂದು ಸರಳ ಆಲೋಚನೆಯೊಂದಿಗೆ ಪ್ರಾರಂಭವಾಯಿತು — ಗುಣಮಟ್ಟದ ಸಸ್ಯಗಳನ್ನು ಮತ್ತು ತೋಟಗಾರಿಕೆ ಉತ್ಪನ್ನಗಳನ್ನು ಎಲ್ಲರಿಗೂ ಲಭ್ಯವಾಗಿಸುವುದು. ಇಂದು, ನಾವು ಆರೋಗ್ಯಕರ ಸಸ್ಯಗಳು, ಗುಣಮಟ್ಟದ ಪಾಟ್‌ಗಳು, ಬೀಜಗಳು ಮತ್ತು ತೋಟದ ಅಗತ್ಯ ವಸ್ತುಗಳ ವಿಶಾಲ ಶ್ರೇಣಿಯನ್ನು ನೀಡುವ ಬೆಳೆಯುತ್ತಿರುವ ಸಸ್ಯ ಪ್ರೇಮಿಗಳ ಸಮುದಾಯವಾಗಿದ್ದೇವೆ. ಹಸಿರು ಜೀವನವನ್ನು ಪ್ರೇರೇಪಿಸುವುದು ಮತ್ತು ಸುಂದರ, ಸುಸ್ಥಿರ ಸ್ಥಳಗಳನ್ನು ರಚಿಸಲು ನಿಮಗೆ ಸಹಾಯ ಮಾಡುವುದು ನಮ್ಮ ಗುರಿ.",
    "Learn More": "ಇನ್ನಷ್ಟು ತಿಳಿಯಿರಿ",
    "A hand holding a small potted plant - From Seed to Green": "ಒಂದು ಸಣ್ಣ ಪಾಟ್ ಸಸ್ಯವನ್ನು ಹಿಡಿದಿರುವ ಕೈ - ಬೀಜದಿಂದ ಹಸಿರಿಗೆ",
    "Years Experience": "ವರ್ಷಗಳ ಅನುಭವ",
    "Plants Delivered": "ವಿತರಿಸಿದ ಸಸ್ಯಗಳು",
    "Plant Varieties": "ಸಸ್ಯ ಪ್ರಭೇದಗಳು",
    "Happy Customers": "ಸಂತೃಪ್ತ ಗ್ರಾಹಕರು",
    "OUR VISION": "ನಮ್ಮ ದೃಷ್ಟಿಕೋನ",
    "A Greener Tomorrow": "ಒಂದು ಹಸಿರು ನಾಳೆ",
    "To be a leading nursery brand that inspires everyone to create healthier, greener and more beautiful spaces, while promoting sustainable living for future generations.": "ಆರೋಗ್ಯಕರ, ಹಸಿರು ಮತ್ತು ಹೆಚ್ಚು ಸುಂದರವಾದ ಸ್ಥಳಗಳನ್ನು ರಚಿಸಲು ಎಲ್ಲರನ್ನು ಪ್ರೇರೇಪಿಸುವ ಪ್ರಮುಖ ನರ್ಸರಿ ಬ್ರ್ಯಾಂಡ್ ಆಗುವುದು, ಅದೇ ಸಮಯದಲ್ಲಿ ಭವಿಷ್ಯದ ಪೀಳಿಗೆಗಳಿಗಾಗಿ ಸುಸ್ಥಿರ ಜೀವನವನ್ನು ಉತ್ತೇಜಿಸುವುದು.",
